1	// Package vision implements Qwen-Image-2.1's vision tower on the CPU — the
2	// 27-layer ViT inside the Qwen3-VL text encoder that turns a condition
3	// image into the context an *edit* is conditioned on (IMAGE.md Q8).
4	//
5	// It is the largest genuinely new port of the Z-Image migration, and the
6	// thing to understand before reading it is what its output is for. The DiT
7	// overwrites every image-slot row of the joint sequence with VAE latents,
8	// so **none of this tensor reaches the transformer directly**. What reaches
9	// it is whatever the surrounding *text* tokens absorbed from these rows
10	// inside the text encoder's own attention. The tower conditions the text;
11	// the VAE conditions the pixels. That is why an edit needs both and why
12	// neither substitutes for the other.
13	//
14	// Five things here are not what a plain ViT would do, and each is a place a
15	// plausible-looking port gives a wrong answer:
16	//
17	//  1. **Token order is 2x2-block-major, not raster.** Patches are laid out
18	//     so that every four consecutive rows are one spatial merge block, which
19	//     is what lets the merger concatenate rows rather than gather. The
20	//     position ids carry that order (blockOrder below) and the packing of
21	//     pixels has to agree with it.
22	//  2. **The position embedding is interpolated.** The checkpoint holds
23	//     48x48 = 2304 learned positions and any image grid is a bilinear
24	//     resample of them — four (index, weight) pairs per patch, align_corners
25	//     true. Nothing about the grid is stored; it is recomputed per image.
26	//  3. **Two different GELUs.** The block MLP uses the tanh approximation
27	//     (config hidden_act is gelu_pytorch_tanh); both mergers use nn.GELU(),
28	//     which is the exact erf one. They differ by ~1e-3 at the knee, which is
29	//     small enough to look like noise and large enough to matter after 27
30	//     layers.
31	//  4. **Two different mergers.** The output merger normalizes each 1152-wide
32	//     row and *then* concatenates four of them; the three deepstack mergers
33	//     concatenate first and normalize the 4608-wide result
34	//     (use_postshuffle_norm). Their LayerNorms are different widths in the
35	//     checkpoint, so loading proves which is which — but running the wrong
36	//     one produces numbers, not an error.
37	//  5. **Axial rope over halves.** cos/sin are built from 18 inverse
38	//     frequencies per axis, concatenated h-then-w to 36 and duplicated to
39	//     the 72-wide head, and the rotation is the NeoX halves convention —
40	//     *not* the adjacent-pair complex rotation the DiT uses. The two live in
41	//     the same repository and are not interchangeable.
42	//
43	// Everything is gated stage by stage against reference/out/qi21vision.
44	package vision
45	
46	import (
47		"fmt"
48		"math"
49	
50		"strix-halo-vulkan/zimage/qwen"
51	)
52	
53	// Config mirrors the vision half of text_encoder/config.json.
54	type Config struct {
55		Depth                 int    `json:"depth"`
56		HiddenSize            int    `json:"hidden_size"`
57		NumHeads              int    `json:"num_heads"`
58		IntermediateSize      int    `json:"intermediate_size"`
59		HiddenAct             string `json:"hidden_act"`
60		PatchSize             int    `json:"patch_size"`
61		SpatialMergeSize      int    `json:"spatial_merge_size"`
62		TemporalPatchSize     int    `json:"temporal_patch_size"`
63		InChannels            int    `json:"in_channels"`
64		NumPositionEmbeddings int    `json:"num_position_embeddings"`
65		OutHiddenSize         int    `json:"out_hidden_size"`
66		DeepstackIndexes      []int  `json:"deepstack_visual_indexes"`
67	}
68	
69	// HeadDim is the attention head width, 72 here.
70	func (c *Config) HeadDim() int { return c.HiddenSize / c.NumHeads }
71	
72	// GridPerSide is the side of the learned position grid, 48 here.
73	func (c *Config) GridPerSide() int {
74		return int(math.Round(math.Sqrt(float64(c.NumPositionEmbeddings))))
75	}
76	
77	// PatchElems is how many values one patch of pixel_values carries:
78	// channels x temporal x patch x patch, 1536 here.
79	func (c *Config) PatchElems() int {
80		return c.InChannels * c.TemporalPatchSize * c.PatchSize * c.PatchSize
81	}
82	
83	// normEps is every LayerNorm's epsilon in the tower.
84	const normEps = 1e-6
85	
86	// Linear is a row-major [Out, In] weight and an optional bias.
87	type Linear struct {
88		In, Out int
89		Weight  []float32 // [Out, In]
90		Bias    []float32 // [Out] or nil
91	}
92	
93	// Apply computes x W^T + b over the rows of x.
94	func (l *Linear) Apply(x *qwen.Mat) (*qwen.Mat, error) {
95		if x.Cols != l.In {
96			return nil, fmt.Errorf("vision: linear %d->%d applied to %d columns", l.In, l.Out, x.Cols)
97		}
98		out := qwen.NewMat(x.Rows, l.Out)
99		for r := 0; r < x.Rows; r++ {
100			row := x.Row(r)
101			dst := out.Row(r)
102			for o := 0; o < l.Out; o++ {
103				w := l.Weight[o*l.In : (o+1)*l.In]
104				var acc float64
105				for i, v := range row {
106					acc += float64(v) * float64(w[i])
107				}
108				if l.Bias != nil {
109					acc += float64(l.Bias[o])
110				}
111				dst[o] = float32(acc)
112			}
113		}
114		return out, nil
115	}
116	
117	// LayerNorm is the affine, mean-subtracting norm the tower uses everywhere.
118	type LayerNorm struct {
119		Weight, Bias []float32
120	}
121	
122	// Apply normalizes each row in place-safe fashion, returning a fresh matrix.
123	func (n *LayerNorm) Apply(x *qwen.Mat) (*qwen.Mat, error) {
124		if len(n.Weight) != x.Cols {
125			return nil, fmt.Errorf("vision: layer norm of width %d over %d columns", len(n.Weight), x.Cols)
126		}
127		out := qwen.NewMat(x.Rows, x.Cols)
128		for r := 0; r < x.Rows; r++ {
129			row, dst := x.Row(r), out.Row(r)
130			var mean float64
131			for _, v := range row {
132				mean += float64(v)
133			}
134			mean /= float64(len(row))
135			var varsum float64
136			for _, v := range row {
137				d := float64(v) - mean
138				varsum += d * d
139			}
140			inv := 1 / math.Sqrt(varsum/float64(len(row))+normEps)
141			for i, v := range row {
142				dst[i] = float32((float64(v)-mean)*inv*float64(n.Weight[i]) + float64(n.Bias[i]))
143			}
144		}
145		return out, nil
146	}
147	
148	// geluTanh is the block MLP's activation (config hidden_act).
149	func geluTanh(x float64) float64 {
150		const c = 0.7978845608028654 // sqrt(2/pi)
151		return 0.5 * x * (1 + math.Tanh(c*(x+0.044715*x*x*x)))
152	}
153	
154	// geluErf is nn.GELU()'s, which is what both mergers use.
155	func geluErf(x float64) float64 { return 0.5 * x * (1 + math.Erf(x/math.Sqrt2)) }
156	
157	func applyAct(m *qwen.Mat, f func(float64) float64) {
158		for i, v := range m.Data {
159			m.Data[i] = float32(f(float64(v)))
160		}
161	}
162	
163	// MLP is the block's feed-forward: fc1, GELU, fc2.
164	//
165	// Act is a field rather than a constant because the tower uses *two*
166	// different GELUs -- the tanh approximation here and the exact erf one in
167	// the mergers -- and which is which is a property of the checkpoint that
168	// deserves to be visible rather than buried in a call. Load sets it; the
169	// negative control in vision_test.go swaps it.
170	type MLP struct {
171		FC1, FC2 Linear
172		Act      func(float64) float64
173	}
174	
175	func (m *MLP) Forward(x *qwen.Mat) (*qwen.Mat, error) {
176		h, err := m.FC1.Apply(x)
177		if err != nil {
178			return nil, err
179		}
180		applyAct(h, m.Act)
181		return m.FC2.Apply(h)
182	}
183	
184	// Attention is the block's full (unmasked) self-attention over the image's
185	// patches. One condition image is one sequence, so the reference's
186	// cu_seqlens chunking degenerates to a single chunk and there is no mask.
187	type Attention struct {
188		QKV, Proj Linear
189		NumHeads  int
190	}
191	
192	func (a *Attention) Forward(x *qwen.Mat, rope *Rope) (*qwen.Mat, error) {
193		n, dim := x.Rows, x.Cols
194		hd := dim / a.NumHeads
195		qkv, err := a.QKV.Apply(x)
196		if err != nil {
197			return nil, err
198		}
199		// qkv rows are [3, heads, headDim] — the reference reshapes to
200		// (seq, 3, heads, -1) and permutes, so q is the first `dim` values of
201		// each row, k the second and v the third.
202		q := qwen.NewMat(n, dim)
203		k := qwen.NewMat(n, dim)
204		v := qwen.NewMat(n, dim)
205		for r := 0; r < n; r++ {
206			row := qkv.Row(r)
207			copy(q.Row(r), row[0:dim])
208			copy(k.Row(r), row[dim:2*dim])
209			copy(v.Row(r), row[2*dim:3*dim])
210		}
211		rope.Apply(q, a.NumHeads, hd)
212		rope.Apply(k, a.NumHeads, hd)
213	
214		ctx := qwen.NewMat(n, dim)
215		scale := 1 / math.Sqrt(float64(hd))
216		scores := make([]float64, n)
217		for h := 0; h < a.NumHeads; h++ {
218			off := h * hd
219			for i := 0; i < n; i++ {
220				qi := q.Row(i)[off : off+hd]
221				max := math.Inf(-1)
222				for j := 0; j < n; j++ {
223					kj := k.Row(j)[off : off+hd]
224					var dot float64
225					for d := 0; d < hd; d++ {
226						dot += float64(qi[d]) * float64(kj[d])
227					}
228					scores[j] = dot * scale
229					if scores[j] > max {
230						max = scores[j]
231					}
232				}
233				var sum float64
234				for j := range scores {
235					scores[j] = math.Exp(scores[j] - max)
236					sum += scores[j]
237				}
238				dst := ctx.Row(i)[off : off+hd]
239				for d := 0; d < hd; d++ {
240					var acc float64
241					for j := 0; j < n; j++ {
242						acc += scores[j] * float64(v.Row(j)[off+d])
243					}
244					dst[d] = float32(acc / sum)
245				}
246			}
247		}
248		return a.Proj.Apply(ctx)
249	}
250	
251	// Block is one of the 27: pre-norm attention and pre-norm MLP, each with a
252	// residual.
253	type Block struct {
254		Norm1, Norm2 LayerNorm
255		Attn         Attention
256		MLP          MLP
257	}
258	
259	func (b *Block) Forward(x *qwen.Mat, rope *Rope) (*qwen.Mat, error) {
260		h, err := b.Norm1.Apply(x)
261		if err != nil {
262			return nil, err
263		}
264		if h, err = b.Attn.Forward(h, rope); err != nil {
265			return nil, err
266		}
267		addInto(x, h)
268		if h, err = b.Norm2.Apply(x); err != nil {
269			return nil, err
270		}
271		if h, err = b.MLP.Forward(h); err != nil {
272			return nil, err
273		}
274		addInto(x, h)
275		return x, nil
276	}
277	
278	func addInto(dst, src *qwen.Mat) {
279		for i := range dst.Data {
280			dst.Data[i] += src.Data[i]
281		}
282	}
283	
284	// Merger turns `merge` consecutive tower rows into one 4096-wide row.
285	//
286	// PostShuffleNorm is the whole difference between the output merger and the
287	// three deepstack ones, and it moves the LayerNorm across the concatenation:
288	// false normalizes each 1152-wide row first, true normalizes the 4608-wide
289	// concatenation. The checkpoint's norm widths say which a given merger is.
290	type Merger struct {
291		PostShuffleNorm bool
292		Merge           int // rows per output row, 4 here
293		Norm            LayerNorm
294		FC1, FC2        Linear
295		Act             func(float64) float64
296	}
297	
298	func (m *Merger) Forward(x *qwen.Mat) (*qwen.Mat, error) {
299		if x.Rows%m.Merge != 0 {
300			return nil, fmt.Errorf("vision: %d rows do not group into %ds", x.Rows, m.Merge)
301		}
302		var shuffled *qwen.Mat
303		if m.PostShuffleNorm {
304			shuffled = reshape(x, m.Merge)
305			normed, err := m.Norm.Apply(shuffled)
306			if err != nil {
307				return nil, err
308			}
309			shuffled = normed
310		} else {
311			normed, err := m.Norm.Apply(x)
312			if err != nil {
313				return nil, err
314			}
315			shuffled = reshape(normed, m.Merge)
316		}
317		h, err := m.FC1.Apply(shuffled)
318		if err != nil {
319			return nil, err
320		}
321		applyAct(h, m.Act)
322		return m.FC2.Apply(h)
323	}
324	
325	// reshape concatenates every `merge` consecutive rows into one. It is a
326	// view in torch and a copy here; at 256 rows of 1152 that is 1 MB.
327	func reshape(x *qwen.Mat, merge int) *qwen.Mat {
328		out := qwen.NewMat(x.Rows/merge, x.Cols*merge)
329		copy(out.Data, x.Data)
330		return out
331	}
332	
333	// Model is the whole tower.
334	type Model struct {
335		Cfg Config
336		// PatchProj is the Conv3d patch embedding, which at one patch per
337		// window is exactly a linear over the 1536 flattened values.
338		PatchProj Linear
339		// PosEmbed is the [2304, 1152] learned position grid.
340		PosEmbed  []float32
341		Blocks    []Block
342		Deepstack []Merger
343		Merger    Merger
344		// RopePairs forces the rotation convention qimage/dit uses, which is
345		// wrong here. See Rope.Pairs: it exists so the gate can be shown to
346		// catch the swap.
347		RopePairs bool
348	}
349	
350	// Output is what one condition image becomes.
351	type Output struct {
352		// Merged is [tokens, 4096] — one row per 2x2 patch group, which is what
353		// is scattered into the `<|image_pad|>` slots of the text sequence.
354		Merged *qwen.Mat
355		// Deepstack is three [tokens, 4096] tensors, added into the text
356		// model's first three layers at the visual positions.
357		Deepstack []*qwen.Mat
358		// Last is the tower's final hidden state, before the merger. Kept
359		// because it is what the stagewise gate compares.
360		Last *qwen.Mat
361	}
362	
363	// Forward runs the tower over one image's patches.
364	//
365	// pixels is [patches, PatchElems] in the processor's own layout and order —
366	// see Patchify, which produces it from an image and is gated against the
367	// dump's pixel_values.
368	func (m *Model) Forward(pixels *qwen.Mat, gridH, gridW int, tap func(name string, x *qwen.Mat)) (*Output, error) {
369		if pixels.Cols != m.Cfg.PatchElems() {
370			return nil, fmt.Errorf("vision: pixel rows are %d wide, want %d", pixels.Cols, m.Cfg.PatchElems())
371		}
372		if pixels.Rows != gridH*gridW {
373			return nil, fmt.Errorf("vision: %d patches for a %dx%d grid", pixels.Rows, gridH, gridW)
374		}
375		h, err := m.PatchProj.Apply(pixels)
376		if err != nil {
377			return nil, err
378		}
379		if tap != nil {
380			tap("patch_embed", h)
381		}
382	
383		pos, err := m.positionEmbedding(gridH, gridW)
384		if err != nil {
385			return nil, err
386		}
387		if tap != nil {
388			tap("pos_embeds", pos)
389		}
390		addInto(h, pos)
391		if tap != nil {
392			tap("block_input", h)
393		}
394	
395		rope := NewRope(&m.Cfg, gridH, gridW)
396		rope.Pairs = m.RopePairs
397		deep := make([]*qwen.Mat, 0, len(m.Deepstack))
398		for i := range m.Blocks {
399			if h, err = m.Blocks[i].Forward(h, rope); err != nil {
400				return nil, fmt.Errorf("vision: block %d: %w", i, err)
401			}
402			if tap != nil {
403				tap(fmt.Sprintf("block%d_out", i), h)
404			}
405			for j, idx := range m.Cfg.DeepstackIndexes {
406				if idx != i {
407					continue
408				}
409				f, err := m.Deepstack[j].Forward(h)
410				if err != nil {
411					return nil, fmt.Errorf("vision: deepstack merger %d: %w", j, err)
412				}
413				deep = append(deep, f)
414			}
415		}
416		if tap != nil {
417			tap("last_hidden", h)
418		}
419		merged, err := m.Merger.Forward(h)
420		if err != nil {
421			return nil, err
422		}
423		return &Output{Merged: merged, Deepstack: deep, Last: h}, nil
424	}
