1	package vision
2	
3	import (
4		"math"
5	
6		"strix-halo-vulkan/zimage/qwen"
7	)
8	
9	// The tower's two geometric pieces, together because they share one fact:
10	// **the token order is 2x2-block-major, not raster**. Both the position
11	// grid and the rope table are indexed by that order, and so is the pixel
12	// packing; get it wrong and every stage still produces plausible numbers.
13	
14	// blockOrder maps a token index to the (row, col) patch it holds.
15	//
16	// The reference builds it by reshaping an h x w index grid to
17	// (h/m, m, w/m, m), transposing the middle two axes and flattening — which
18	// is "walk the merge blocks in raster order, and inside each block walk its
19	// m x m patches in raster order". Written out rather than reshaped, because
20	// the transpose is the entire content of the layout and a reshape hides it.
21	func blockOrder(gridH, gridW, merge int) [][2]int {
22		out := make([][2]int, 0, gridH*gridW)
23		for by := 0; by < gridH/merge; by++ {
24			for bx := 0; bx < gridW/merge; bx++ {
25				for dy := 0; dy < merge; dy++ {
26					for dx := 0; dx < merge; dx++ {
27						out = append(out, [2]int{by*merge + dy, bx*merge + dx})
28					}
29				}
30			}
31		}
32		return out
33	}
34	
35	// positionEmbedding resamples the learned 48x48 grid onto this image's
36	// grid, bilinearly with align_corners.
37	//
38	// This is the piece with the most ways to be subtly wrong, so it is written
39	// the way the reference computes it rather than the way one would write a
40	// resampler: four (index, weight) pairs per patch, the weights being the
41	// bilinear products, and the four indices the corners of the source cell.
42	// align_corners means the *endpoints* map to endpoints, so the source
43	// coordinate of destination index i out of n is i*(48-1)/(n-1) — and for
44	// n == 1 that is 0 rather than a division by zero.
45	func (m *Model) positionEmbedding(gridH, gridW int) (*qwen.Mat, error) {
46		side := m.Cfg.GridPerSide()
47		dim := m.Cfg.HiddenSize
48		order := blockOrder(gridH, gridW, m.Cfg.SpatialMergeSize)
49	
50		out := qwen.NewMat(len(order), dim)
51		for t, rc := range order {
52			sy := srcCoord(rc[0], gridH, side)
53			sx := srcCoord(rc[1], gridW, side)
54			y0, x0 := int(math.Floor(sy)), int(math.Floor(sx))
55			y1, x1 := min(y0+1, side-1), min(x0+1, side-1)
56			fy, fx := sy-float64(y0), sx-float64(x0)
57			dst := out.Row(t)
58			for _, c := range [4]struct {
59				idx int
60				w   float64
61			}{
62				{y0*side + x0, (1 - fy) * (1 - fx)},
63				{y0*side + x1, (1 - fy) * fx},
64				{y1*side + x0, fy * (1 - fx)},
65				{y1*side + x1, fy * fx},
66			} {
67				if c.w == 0 {
68					continue
69				}
70				row := m.PosEmbed[c.idx*dim : (c.idx+1)*dim]
71				for i, v := range row {
72					dst[i] += float32(c.w * float64(v))
73				}
74			}
75		}
76		return out, nil
77	}
78	
79	// srcCoord is align_corners=true's destination-to-source map.
80	func srcCoord(i, n, side int) float64 {
81		if n <= 1 {
82			return 0
83		}
84		return float64(i) * float64(side-1) / float64(n-1)
85	}
86	
87	// Rope is the tower's axial 2-D rotary table: cos and sin of [tokens,
88	// headDim], already in the layout the rotation reads.
89	//
90	// The frequencies are built over headDim/2 = 36 with a stride of 2, giving
91	// 18 per axis; h's 18 and w's 18 are concatenated to 36 and the 36
92	// duplicated to 72. The rotation is then **NeoX halves** -- the first half
93	// of the head against the second -- and not the adjacent-pair complex
94	// rotation the DiT's RoPE uses. Both conventions live in this repository
95	// and swapping them is a negative control in dit_test.go for exactly that
96	// reason.
97	type Rope struct {
98		Cos, Sin *qwen.Mat
99		// Pairs selects the *other* convention -- adjacent-pair complex
100		// rotation, which is what qimage/dit's RoPE does. It is wrong here and
101		// is selectable for exactly that reason: the two conventions live in
102		// this repository, a swap between them produces numbers rather than an
103		// error, and a bound that has never been shown to catch one is not a
104		// bound. vision_test.go's negative control is its only caller.
105		Pairs bool
106	}
107	
108	// NewRope builds the table for one image's grid.
109	func NewRope(cfg *Config, gridH, gridW int) *Rope {
110		hd := cfg.HeadDim()
111		spatial := hd / 2
112		nf := spatial / 2 // 18
113		inv := make([]float64, nf)
114		for i := range inv {
115			inv[i] = 1 / math.Pow(10000, float64(2*i)/float64(spatial))
116		}
117		order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
118		cos := qwen.NewMat(len(order), hd)
119		sin := qwen.NewMat(len(order), hd)
120		for t, rc := range order {
121			c, s := cos.Row(t), sin.Row(t)
122			for i, f := range inv {
123				ah := float64(rc[0]) * f
124				aw := float64(rc[1]) * f
125				// freq_hw = [h's 18 ++ w's 18]; the table is freq_hw twice.
126				for _, base := range [2]int{0, spatial} {
127					c[base+i] = float32(math.Cos(ah))
128					s[base+i] = float32(math.Sin(ah))
129					c[base+nf+i] = float32(math.Cos(aw))
130					s[base+nf+i] = float32(math.Sin(aw))
131				}
132			}
133		}
134		return &Rope{Cos: cos, Sin: sin}
135	}
136	
137	// Apply rotates every head of every row in place, NeoX halves.
138	func (r *Rope) Apply(x *qwen.Mat, heads, headDim int) {
139		half := headDim / 2
140		for t := 0; t < x.Rows; t++ {
141			row := x.Row(t)
142			cos, sin := r.Cos.Row(t), r.Sin.Row(t)
143			for h := 0; h < heads; h++ {
144				v := row[h*headDim : (h+1)*headDim]
145				if r.Pairs {
146					for i := 0; i < half; i++ {
147						a, b := float64(v[2*i]), float64(v[2*i+1])
148						v[2*i] = float32(a*float64(cos[2*i]) - b*float64(sin[2*i]))
149						v[2*i+1] = float32(b*float64(cos[2*i+1]) + a*float64(sin[2*i+1]))
150					}
151					continue
152				}
153				for i := 0; i < half; i++ {
154					a, b := float64(v[i]), float64(v[i+half])
155					v[i] = float32(a*float64(cos[i]) - b*float64(sin[i]))
156					v[i+half] = float32(b*float64(cos[i+half]) + a*float64(sin[i+half]))
157				}
158			}
159		}
160	}
161	
162	// Patchify turns an image into the processor's `pixel_values`: one row per
163	// patch, in block-major order, each row channels-then-temporal-then-pixels.
164	//
165	// img is [3, H, W] already normalized to [-1, 1] (the processor's mean and
166	// std are both 0.5, so that is exactly its output), and the temporal axis is
167	// the same frame repeated TemporalPatchSize times — a still image entering a
168	// video model.
169	func (cfg *Config) Patchify(img []float32, h, w int) (*qwen.Mat, int, int, error) {
170		p := cfg.PatchSize
171		gridH, gridW := h/p, w/p
172		order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
173		out := qwen.NewMat(len(order), cfg.PatchElems())
174		plane := h * w
175		for t, rc := range order {
176			dst := out.Row(t)
177			i := 0
178			for c := 0; c < cfg.InChannels; c++ {
179				for tp := 0; tp < cfg.TemporalPatchSize; tp++ {
180					for py := 0; py < p; py++ {
181						srcRow := (rc[0]*p + py) * w
182						for px := 0; px < p; px++ {
183							dst[i] = img[c*plane+srcRow+rc[1]*p+px]
184							i++
185						}
186					}
187				}
188			}
189		}
190		return out, gridH, gridW, nil
191	}
