48			return nil
49		}
50		t, err := l.set.Get(l.prefix + name)
51		if err != nil {
52			l.err = err
53			return nil
54		}
55		v, err := t.F32(nil)
56		if err != nil {
57			l.err = err
58			return nil
59		}
60		if want > 0 && len(v) != want {
61			l.err = fmt.Errorf("vision: %s has %d values, want %d", name, len(v), want)
62			return nil
63		}
64		return v
65	}
