105	// walk the first two without staging 1.0 GB of ViT. Zero or negative means
106	// all of them; a deepstack merger whose layer is past the cap is skipped.
107	func Load(dir string, cfg *Config, blocks int) (*Model, error) {
108		set, err := safetensors.OpenSet(dir)
109		if err != nil {
110			return nil, err
111		}
112		defer set.Close()
113		if blocks <= 0 || blocks > cfg.Depth {
114			blocks = cfg.Depth
115		}
116		l := &loader{set: set, prefix: "model.visual."}
117	
118		m := &Model{Cfg: *cfg}
119		// The Conv3d patch embedding is one linear: its kernel is exactly one
120		// patch, so [1152, 3, 2, 16, 16] is [1152, 1536] row-major already.
121		m.PatchProj = l.linear("patch_embed.proj", cfg.HiddenSize, cfg.PatchElems())
122		m.PosEmbed = l.f32("pos_embed.weight", cfg.NumPositionEmbeddings*cfg.HiddenSize)
123	
124		for i := 0; i < blocks; i++ {
125			p := fmt.Sprintf("blocks.%d.", i)
126			m.Blocks = append(m.Blocks, Block{
127				Norm1: l.norm(p+"norm1", cfg.HiddenSize),
128				Norm2: l.norm(p+"norm2", cfg.HiddenSize),
129				Attn: Attention{
130					QKV:      l.linear(p+"attn.qkv", 3*cfg.HiddenSize, cfg.HiddenSize),
131					Proj:     l.linear(p+"attn.proj", cfg.HiddenSize, cfg.HiddenSize),
132					NumHeads: cfg.NumHeads,
133				},
134				MLP: MLP{
135					FC1: l.linear(p+"mlp.linear_fc1", cfg.IntermediateSize, cfg.HiddenSize),
136					FC2: l.linear(p+"mlp.linear_fc2", cfg.HiddenSize, cfg.IntermediateSize),
137					Act: geluTanh, // config hidden_act; the mergers use the erf one
138				},
139			})
140		}
141		for j, idx := range cfg.DeepstackIndexes {
142			if idx >= blocks {
143				continue
144			}
145			m.Deepstack = append(m.Deepstack, l.merger(fmt.Sprintf("deepstack_merger_list.%d", j), cfg, true))
146		}
147		m.Merger = l.merger("merger", cfg, false)
148	
149		if l.err != nil {
150			return nil, l.err
151		}
152		return m, nil
153	}
