178			}
179		}
180		if cfg.RopeTheta != m.RopeTheta {
181			t.Errorf("rope_theta is %g, want %g", cfg.RopeTheta, m.RopeTheta)
182		}
183		if cfg.Prefix != "model.language_model." {
184			t.Errorf("prefix is %q", cfg.Prefix)
185		}
186		if m.MRopeGap != 0 {
187			t.Errorf("text-only mrope differs from plain RoPE by %g; this package assumes 0", m.MRopeGap)
188		}
189		if g := m.Prompts["en"].PrenormGap; g != 0 {
190			t.Errorf("hooked pre-norm state differs from the pipeline's output by %g", g)
191		}
192		if m.SysPrompt != SysPrompt {
193			t.Errorf("system prompt is %q, want %q", SysPrompt, m.SysPrompt)
