223	// TestTokenizer checks the Go tokenizer against the processor's ids for all
224	// three prompts, template included.
225	func TestTokenizer(t *testing.T) {
226		m := loadManifest(t)
227		tok := loadTok(t)
228		for label, p := range m.Prompts {
229			got, err := EncodePrompt(tok, p.Prompt)
