231				t.Fatal(err)
232			}
233			if len(got) != len(p.IDs) {
234				t.Fatalf("%s: %d ids, want %d", label, len(got), len(p.IDs))
235			}
236			for i := range got {
237				if got[i] != p.IDs[i] {
238					t.Fatalf("%s: id %d is %d, want %d", label, i, got[i], p.IDs[i])
