246	// the model itself used (captured by hook in the dump). The dump holds
247	// cat(freqs, freqs) over the full width; qwen keeps the distinct half.
248	func TestRoPETable(t *testing.T) {
249		m := loadManifest(t)
250		p := m.Prompts["en"]
251		cos, sin := loadRef(t, m, "en_rope_cos"), loadRef(t, m, "en_rope_sin")
252		rope := qwen.NewRoPE(m.HeadDim, p.Seq, m.RopeTheta)
253		half := m.HeadDim / 2
254		gotCos, gotSin := qwen.NewMat(p.Seq, m.HeadDim), qwen.NewMat(p.Seq, m.HeadDim)
255		for pos := 0; pos < p.Seq; pos++ {
256			for i := 0; i < half; i++ {
257				gotCos.Row(pos)[i] = rope.Cos[pos*half+i]
258				gotCos.Row(pos)[i+half] = rope.Cos[pos*half+i]
259				gotSin.Row(pos)[i] = rope.Sin[pos*half+i]
260				gotSin.Row(pos)[i+half] = rope.Sin[pos*half+i]
261			}
262		}
