267	// TestLayerWalk runs the first two decoder layers over the English prompt
268	// and compares each hidden state — the test that says *which* layer is wrong
269	// when TestEncoder's output is. Two layers and the embedding table are
270	// ~4.4 GB fp32.
271	func TestLayerWalk(t *testing.T) {
272		m := loadManifest(t)
273		cfg, err := LoadConfig(encoder)
274		if err != nil {
275			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
276		}
277		model, err := qwen.LoadWith(encoder, cfg, 2)
278		if err != nil {
279			t.Fatal(err)
280		}
281		tr := qwen.Trace{}
282		if _, err := model.Forward(m.Prompts["en"].IDs, tr); err != nil {
283			t.Fatal(err)
284		}
285		compare(t, "en_embed_tokens", tr["embeddings"], loadRef(t, m, "en_embed_tokens"))
286		compare(t, "en_layer0_out", tr["hidden_1"], loadRef(t, m, "en_layer0_out"))
287		compare(t, "en_layer1_out", tr["hidden_2"], loadRef(t, m, "en_layer1_out"))
288	}
