290	// TestEncoder is Q1's CPU acceptance gate: all 36 layers, no final norm,
291	// three prompts, against the embeddings the diffusers pipeline hands the
292	// DiT. Loads ~34 GB of fp32 weights.
293	func TestEncoder(t *testing.T) {
294		if testing.Short() {
295			t.Skip("loads 34 GB of fp32 weights")
296		}
297		m := loadManifest(t)
298		cfg, err := LoadConfig(encoder)
299		if err != nil {
300			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
301		}
302		model, err := qwen.LoadWith(encoder, cfg, cfg.NumLayers)
303		if err != nil {
304			t.Fatal(err)
305		}
306		drop := m.DropIdx
307	
308		for _, label := range []string{"en", "cjk", "empty"} {
309			p := m.Prompts[label]
310			out, err := model.Forward(p.IDs, nil)
311			if err != nil {
312				t.Fatal(err)
313			}
314			if label == "en" {
315				compareAt(t, "en_last_prenorm", out, loadRef(t, m, "en_last_prenorm"), deepTol)
316			}
317			embeds, err := Drop(out, drop)
318			if err != nil {
319				t.Fatal(err)
320			}
321			compareAt(t, label+"_prompt_embeds", embeds, loadRef(t, m, label+"_prompt_embeds"), deepTol)
322		}
323	}
