12		"strix-halo-vulkan/safetensors"
13		"strix-halo-vulkan/zimage/qwen"
14	)
15	
16	// The reference comes from reference/dump_qi21_vision.py: the real Qwen3-VL
17	// vision tower in fp32 on CPU over a deterministic 256x256 RGBA card, every
18	// stage hooked. Regenerate with:
19	//
20	//	.venv/bin/python reference/dump_qi21_vision.py
21	const (
22		refDir  = "../../reference/out/qi21vision"
23		encoder = "../../models/Qwen-Image-2.1/text_encoder"
24	)
25	
26	type manifest struct {
27		Seq               int     `json:"seq"`
28		Size              int     `json:"size"`
29		DropIdx           int     `json:"drop_idx"`
30		GridTHW           [][]int `json:"grid_thw"`
31		ImagePadPositions []int   `json:"image_pad_positions"`
32		Vision            struct {
33			Depth            int   `json:"depth"`
34			DeepstackIndexes []int `json:"deepstack_visual_indexes"`
35		} `json:"vision"`
36		Tensors map[string]struct {
37			Shape  []int   `json:"shape"`
38			Count  int     `json:"count"`
39			Sum    float64 `json:"sum"`
40			AbsMax float64 `json:"absmax"`
41		} `json:"tensors"`
42	}
43	
44	func loadManifest(t *testing.T) *manifest {
45		t.Helper()
46		buf, err := os.ReadFile(filepath.Join(refDir, "manifest.json"))
47		if err != nil {
48			t.Skipf("no reference dump in %s (%v); run reference/dump_qi21_vision.py", refDir, err)
49		}
50		var m manifest
51		if err := json.Unmarshal(buf, &m); err != nil {
52			t.Fatal(err)
53		}
54		return &m
55	}
56	
57	// loadRef reads a dumped tensor as a matrix, folding every leading axis into
58	// the row count.
59	func loadRef(t *testing.T, m *manifest, name string) *qwen.Mat {
60		t.Helper()
61		meta, ok := m.Tensors[name]
62		if !ok {
63			t.Fatalf("reference has no tensor %q", name)
64		}
65		raw, err := os.ReadFile(filepath.Join(refDir, name+".bin"))
66		if err != nil {
67			t.Fatal(err)
68		}
69		if len(raw) != meta.Count*4 {
70			t.Fatalf("%s: %d bytes for %d float32", name, len(raw), meta.Count)
71		}
72		data := make([]float32, meta.Count)
73		for i := range data {
74			data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
75		}
76		cols := meta.Shape[len(meta.Shape)-1]
77		return &qwen.Mat{Rows: meta.Count / cols, Cols: cols, Data: data}
78	}
79	
80	// deepTol is the bound for the tower's stages, and it is set the way every
81	// other bound in this vertical is: from the model's own arithmetic rather
82	// than from taste. Both sides are fp32; the drift is summation order through
83	// 27 pre-norm blocks whose residual stream grows to absmax 1.3e4 by the last
84	// hidden state (the dump records it), so the rms floor in `compare` is what
85	// keeps that growth from hiding an error on a small element.
86	//
87	// A structural mistake — the raster token order instead of block-major, the
88	// wrong GELU, the wrong merger norm placement, adjacent-pair rotation
89	// instead of halves — shows at rel >= 1e-1 on the first stage it touches.
90	// TestNegativeControls is that claim measured rather than asserted.
91	const deepTol = 2e-4
92	
93	func compare(t *testing.T, name string, got, want *qwen.Mat) float64 {
94		t.Helper()
95		if got.Rows != want.Rows || got.Cols != want.Cols {
96			t.Fatalf("%s: shape %dx%d, want %dx%d", name, got.Rows, got.Cols, want.Rows, want.Cols)
97		}
98		var sumSq float64
99		for _, v := range want.Data {
100			sumSq += float64(v) * float64(v)
101		}
102		rms := math.Sqrt(sumSq / float64(len(want.Data)))
103		var maxAbs, rel float64
104		for i := range want.Data {
105			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
106			if d > maxAbs {
107				maxAbs = d
108			}
109			if r := d / math.Max(math.Abs(float64(want.Data[i])), math.Max(rms, 1e-12)); r > rel {
110				rel = r
111			}
112		}
113		if rel > deepTol {
114			t.Errorf("%-20s %dx%d: max abs %.4g, rel %.3g, rms %.4g > %.0e",
115				name, got.Rows, got.Cols, maxAbs, rel, rms, deepTol)
116			return rel
117		}
118		t.Logf("%-20s %5dx%-5d max abs %.3g  rms %.4g  rel %.2g", name, got.Rows, got.Cols, maxAbs, rms, rel)
119		return rel
120	}
121	
122	func load(t *testing.T, blocks int) (*Config, *Model, *manifest) {
123		t.Helper()
124		m := loadManifest(t)
125		cfg, err := LoadConfig(encoder)
126		if err != nil {
127			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
128		}
129		model, err := Load(encoder, cfg, blocks)
130		if err != nil {
131			t.Fatal(err)
132		}
133		return cfg, model, m
134	}
135	
136	// TestPatchify checks the processor's pixel layout — block-major token
137	// order, channels-then-temporal-then-pixels inside a row, the still frame
138	// repeated on the temporal axis — against what the processor actually
139	// emitted. It needs no weights, which is why it runs first: every later
140	// stage is reading these rows.
141	func TestPatchify(t *testing.T) {
142		m := loadManifest(t)
143		cfg, err := LoadConfig(encoder)
144		if err != nil {
145			t.Skipf("no text encoder checkpoint at %s (%v)", encoder, err)
146		}
147		card := loadRef(t, m, "card_vision_rgb") // [1, 3, H, W] folded to rows
148		h, w := m.Size, m.Size
149		got, gridH, gridW, err := cfg.Patchify(card.Data, h, w)
150		if err != nil {
151			t.Fatal(err)
152		}
153		if g := m.GridTHW[0]; gridH != g[1] || gridW != g[2] {
154			t.Fatalf("grid %dx%d, dump says %v", gridH, gridW, g)
155		}
156		compare(t, "pixel_values", got, loadRef(t, m, "pixel_values"))
157	}
158	
159	// TestGeometry checks the two pieces that decide *where* everything goes:
160	// the bilinear resample of the 48x48 learned position grid, and the axial
161	// rope table. Both are pure geometry, so they are exact to fp32 rounding
162	// and a disagreement is a layout bug rather than drift.
163	func TestGeometry(t *testing.T) {
164		cfg, model, m := load(t, 1)
165		gridH, gridW := m.GridTHW[0][1], m.GridTHW[0][2]
166	
167		pos, err := model.positionEmbedding(gridH, gridW)
168		if err != nil {
169			t.Fatal(err)
170		}
171		compare(t, "pos_embeds", pos, loadRef(t, m, "vis_pos_embeds"))
172	
173		rope := NewRope(cfg, gridH, gridW)
174		compare(t, "rope_cos", rope.Cos, loadRef(t, m, "vis_rope_cos"))
175		compare(t, "rope_sin", rope.Sin, loadRef(t, m, "vis_rope_sin"))
176	}
177	
178	// TestTowerPrefix walks the first two blocks, which is enough to catch every
179	// per-block mistake without staging the whole 1.0 GB tower: the patch
180	// embedding, the position sum, and both residual halves twice over.
181	func TestTowerPrefix(t *testing.T) {
182		cfg, model, m := load(t, 2)
183		card := loadRef(t, m, "card_vision_rgb")
184		pixels, gridH, gridW, err := cfg.Patchify(card.Data, m.Size, m.Size)
185		if err != nil {
186			t.Fatal(err)
187		}
188		want := map[string]string{
189			"patch_embed": "vis_patch_embed",
190			"block_input": "vis_block_input",
191			"block0_out":  "vis_block0_out",
192			"block1_out":  "vis_block1_out",
193		}
194		seen := 0
195		_, err = model.Forward(pixels, gridH, gridW, func(name string, x *qwen.Mat) {
196			ref, ok := want[name]
197			if !ok {
198				return
199			}
200			compare(t, name, x, loadRef(t, m, ref))
201			seen++
202		})
203		if err != nil {
204			t.Fatal(err)
205		}
206		if seen != len(want) {
207			t.Fatalf("%d of %d stages compared", seen, len(want))
208		}
209	}
210	
211	// TestTower is the full gate: all 27 blocks, the three deepstack taps at
212	// layers 8/16/24, the last hidden state and the merged rows the text
213	// encoder scatters into its image slots.
214	func TestTower(t *testing.T) {
215		if testing.Short() {
216			t.Skip("stages the whole 27-layer tower")
217		}
218		cfg, model, m := load(t, 0)
219		card := loadRef(t, m, "card_vision_rgb")
220		pixels, gridH, gridW, err := cfg.Patchify(card.Data, m.Size, m.Size)
221		if err != nil {
222			t.Fatal(err)
223		}
224		out, err := model.Forward(pixels, gridH, gridW, func(name string, x *qwen.Mat) {
225			for _, i := range m.Vision.DeepstackIndexes {
226				if name == fmt.Sprintf("block%d_out", i) {
227					compare(t, name, x, loadRef(t, m, "vis_"+name))
228				}
229			}
230		})
231		if err != nil {
232			t.Fatal(err)
233		}
234		compare(t, "last_hidden", out.Last, loadRef(t, m, "vis_last_hidden"))
235		if len(out.Deepstack) != len(m.Vision.DeepstackIndexes) {
236			t.Fatalf("%d deepstack features, want %d", len(out.Deepstack), len(m.Vision.DeepstackIndexes))
237		}
238		for i, f := range out.Deepstack {
239			compare(t, fmt.Sprintf("deepstack%d", i), f, loadRef(t, m, fmt.Sprintf("vis_deepstack%d", i)))
240		}
241		compare(t, "merged", out.Merged, loadRef(t, m, "vis_merged"))
242		// The merged rows are exactly what the encoder scatters into the
243		// `<|image_pad|>` slots — the dump measured that scatter at gap 0
244		// against the model's own inputs_embeds, so matching here is matching
245		// the tensor the text side actually reads.
246		compare(t, "merged_as_scattered", out.Merged, loadRef(t, m, "edit_merged_rows"))
247	}
248	
249	// TestNegativeControls breaks each of the four things this port could
250	// plausibly have got wrong and checks the bound catches it. Without them,
251	// "the token order is block-major", "the two GELUs differ" and "the mergers
252	// normalize in different places" rest on a comparison that might have been
253	// passing for another reason.
254	//
255	// Each runs on the two-block prefix, because every one of them is visible by
256	// block 0 and the whole tower costs 27x as much to say the same.
257	func TestNegativeControls(t *testing.T) {
258		cfg, model, m := load(t, 2)
259		card := loadRef(t, m, "card_vision_rgb")
260		pixels, gridH, gridW, err := cfg.Patchify(card.Data, m.Size, m.Size)
261		if err != nil {
262			t.Fatal(err)
263		}
264		want := loadRef(t, m, "vis_block0_out")
265	
266		// 1. Raster token order instead of 2x2-block-major. The pixels are the
267		// same bytes in a different order, which is exactly the mistake a port
268		// that patchifies rastered would make.
269		raster := qwen.NewMat(pixels.Rows, pixels.Cols)
270		for i, rc := range blockOrder(gridH, gridW, cfg.SpatialMergeSize) {
271			copy(raster.Row(rc[0]*gridW+rc[1]), pixels.Row(i))
272		}
273		control(t, "raster token order", model, raster, gridH, gridW, want)
274	
275		// 2. The exact-erf GELU in the block MLP, where the tanh one belongs.
276		// Both are GELUs; they differ by ~1e-3 around the knee.
277		for i := range model.Blocks {
278			model.Blocks[i].MLP.Act = geluErf
279		}
280		control(t, "erf GELU in the MLP", model, pixels, gridH, gridW, want)
281		for i := range model.Blocks {
282			model.Blocks[i].MLP.Act = geluTanh
283		}
284	
285		// 3. Adjacent-pair rotation instead of NeoX halves -- qimage/dit's
286		// convention, which is one import away from this file.
287		pairs := *model
288		pairs.RopePairs = true
289		control(t, "adjacent-pair rotation", &pairs, pixels, gridH, gridW, want)
290	
291		// 4. The deepstack mergers' norm placement on the output merger. This one
292		// cannot even load -- the checkpoint's `merger.norm` is 1152 wide and a
293		// post-shuffle merger wants 4608 -- so it is asserted as a load failure,
294		// which is the stronger outcome and the reason the widths are checked at
295		// load rather than assumed.
296		set, err := safetensors.OpenSet(encoder)
297		if err != nil {
298			t.Fatal(err)
299		}
300		defer set.Close()
301		l := &loader{set: set, prefix: "model.visual."}
302		l.merger("merger", cfg, true)
303		if l.err == nil {
304			t.Error("loading the output merger as post-shuffle succeeded; the norm widths should have refused it")
305		} else {
306			t.Logf("control %-24s refused at load: %v", "post-shuffle output merger", l.err)
307		}
308	}
309	
310	// control runs the two-block prefix and requires block 0's output to be far
311	// outside the bound.
312	func control(t *testing.T, what string, model *Model, pixels *qwen.Mat, gridH, gridW int, want *qwen.Mat) {
313		t.Helper()
314		var sumSq float64
315		for _, v := range want.Data {
316			sumSq += float64(v) * float64(v)
317		}
318		rms := math.Sqrt(sumSq / float64(len(want.Data)))
319		var rel float64
320		_, err := model.Forward(pixels, gridH, gridW, func(name string, x *qwen.Mat) {
321			if name != "block0_out" {
322				return
323			}
324			for i := range want.Data {
325				d := math.Abs(float64(x.Data[i]) - float64(want.Data[i]))
326				if r := d / math.Max(math.Abs(float64(want.Data[i])), rms); r > rel {
327					rel = r
328				}
329			}
330		})
331		if err != nil {
332			t.Fatalf("%s: %v", what, err)
333		}
334		if rel <= deepTol {
335			t.Errorf("%s still matches at rel %.3g, inside the %.0e bound", what, rel, deepTol)
336			return
337		}
338		t.Logf("control %-24s rel %.3g, %.0fx the bound", what, rel, rel/deepTol)
339	}
