)

type manifest struct {
	Seq               int     `json:"seq"`
	Size              int     `json:"size"`
	DropIdx           int     `json:"drop_idx"`
	GridTHW           [][]int `json:"grid_thw"`
	ImagePadPositions []int   `json:"image_pad_positions"`
	Vision            struct {
		Depth            int   `json:"depth"`
		DeepstackIndexes []int `json:"deepstack_visual_indexes"`
	} `json:"vision"`
