		return zero, fmt.Errorf("textenc: parsing config.json: %w", err)
	}
	s := outer.Text.RopeScaling
	if len(s.Section) != 3 {
		return zero, fmt.Errorf("textenc: mrope_section is %v, want three axes", s.Section)
	}
