		}
	})
	if err != nil {
		t.Fatal(err)
	}
	compare(t, "vis2_last_hidden", out.Last, loadEditRef(t, m, "vis2_last_hidden"))
	compare(t, "vis2_merged", out.Merged, loadEditRef(t, m, "vis2_merged"))
	for i, f := range out.Deepstack {
		compare(t, fmt.Sprintf("vis2_deepstack%d", i), f, loadEditRef(t, m, fmt.Sprintf("vis2_deepstack%d", i)))
	}
}

