184	// GPUDecoder runs the decode graph on a Vulkan device.
185	type GPUDecoder struct {
186		dev *vk.Device
187		cpu *Decoder
188	
189		wbuf *vk.Buffer
190		abuf *vk.Buffer
191	
192		pipes   map[string]*vk.ComputePipeline
193		mods    []*vk.ShaderModule
194		weights *gpuWeights
195	
196		arena arena
197	}
198	
199	// shaderSet is every pipeline the graph uses. Six of the eight are z-image's
200	// unchanged.
201	var shaderSet = map[string][]byte{
202		"conv2d":     shaders.VAEConv2D,
203		"add":        shaders.VAEAdd,
204		"upsample2x": shaders.VAEUpsample2x,
205		"to_rows":    shaders.VAENCHWToRows,
206		"to_nchw":    shaders.VAERowsToNCHWAdd,
207		"linear":     shaders.VAELinear,
208		"transpose":  shaders.VAETranspose,
209		"attention":  shaders.VAEAttentionDim1152,
210		"chnorm":     shaders.QVAEChannelNorm,
211		"dupup":      shaders.QVAEDupUp,
212	}
213	
214	// NewGPUDecoder uploads a loaded decoder's weights, builds its pipelines and
215	// sizes the activation arena for a latentH x latentW latent — which is the
216	// largest the returned decoder will accept, since the arena is allocated
217	// once.
218	func NewGPUDecoder(dev *vk.Device, cpu *Decoder, latentH, latentW int) (*GPUDecoder, error) {
219		if got := cpu.Mid.Attn.QKV.InC; got != midDim {
220			return nil, fmt.Errorf("qvae: mid block is %d channels, the attention kernel is built for %d", got, midDim)
221		}
222		g := &GPUDecoder{
223			dev:     dev,
224			cpu:     cpu,
225			pipes:   make(map[string]*vk.ComputePipeline),
226			weights: &gpuWeights{off: make(map[string]uint32)},
227		}
228		g.flattenWeights()
229	
230		var err error
231		wbytes := len(g.weights.data) * 4
