125		}
126		card := loadRef(t, m, "s256_card")
127		want := loadRef(t, m, "s256_enc_down_blocks.0")
128	
129		// 1. The AvgDown shortcut's temporal factor. At T = 1 it moves no data,
130		// but it decides which source values a group is made of *and* whether a
131		// zero frame is averaged in — so setting it to 1 on a temporal block
132		// scales that shortcut by two.
133		t.Run("avgdown temporal factor", func(t *testing.T) {
134			_, enc, _ := loadGPUEncoder(t, dev, c.H, c.W)
135			broken := *enc
136			broken.Downs = append([]DownBlock(nil), enc.Downs...)
137			hit := false
138			for i := range broken.Downs {
139				if broken.Downs[i].Shortcut.FactorT != 1 {
140					broken.Downs[i].Shortcut.FactorT = 1
141					hit = true
142				}
143			}
144			if !hit {
145				t.Skip("no down block has a temporal factor to break")
146			}
147			g, err := NewGPUEncoder(dev, &broken, c.H, c.W)
148			if err != nil {
