153		})
154	
155		// 2. The stride-2 identity's offset. Keeping (2h, 2w) instead of
156		// (2h+1, 2w+1) is the plausible mistake — it is the subsampling a reader
157		// would write without knowing the padding is (0, 1, 0, 1) — and it is
158		// half a pixel of shift through every downsampler.
159		t.Run("downsample offset", func(t *testing.T) {
160			_, enc, _ := loadGPUEncoder(t, dev, c.H, c.W)
161			broken := *enc
162			broken.Downs = append([]DownBlock(nil), enc.Downs...)
163			for i := range broken.Downs {
